1	import { useEffect, useRef, useState } from 'react';
2	import type { RefObject, SyntheticEvent } from 'react';
3	import { defineMessages, useIntl } from 'react-intl';
4	import { useUiCopy } from 'app/hooks/useUiCopy';
5	import { useForm } from 'react-hook-form';
6	import type { UseFormReturn, FieldValues } from 'react-hook-form';
7	import { useDisclosure } from '@chakra-ui/react';
8	import {
9	  AuthHelpers,
10	  useAuthHelper,
11	  useCustomerType,
12	  useShopperBasketsV2Mutation as useShopperBasketsMutation,
13	} from '@salesforce/commerce-sdk-react';
14	import { useAuthModal, REGISTER_VIEW } from '@salesforce/retail-react-app/app/hooks/use-auth-modal';
15	import { getConfig } from '@salesforce/pwa-kit-runtime/utils/ssr-config';
16	import {
17	  getAuthorizePasswordlessErrorMessage,
18	  getLoginPasswordlessErrorMessage,
19	  getPasswordlessCallbackUrl,
20	} from '@salesforce/retail-react-app/app/utils/auth-utils';
21	import { API_ERROR_MESSAGE } from '@salesforce/retail-react-app/app/constants';
22	import {
23	  setSessionJSONItem,
24	  getSessionJSONItem,
25	  clearSessionJSONItem,
26	  buildRedirectURI,
27	} from '@salesforce/retail-react-app/app/utils/utils';
28	import useMultiSite from '@salesforce/retail-react-app/app/hooks/use-multi-site';
29	import { useCurrentCustomer } from '@salesforce/retail-react-app/app/hooks/use-current-customer';
30	
31	// Matches the ZimmDrawer slide-in animation duration so focus/modal calls land after the
32	// panel is visible and Chakra's FocusLock has initialised.
33	const DRAWER_ANIMATION_DELAY_MS = 150;
34	
35	// Social IDP sign-in triggers a full-page redirect — onAuthSuccess never fires. Persist an
36	// intent before the redirect so the pending wishlist action can be replayed on return.
37	// Keyed by `intentId` (see UseWishlistAuthDrawerParams) rather than a bare flag: the header
38	// and a PDP can both mount their own `useWishlistAuthDrawer` instance on the same returned
39	// page, each with a different `onAuthSuccess` — a bare boolean let whichever instance's
40	// effect ran first steal the intent and fire its own callback instead of the one that
41	// actually initiated the redirect (SFCC-742 review finding).
42	const PENDING_WISHLIST_INTENT_KEY = 'zimmPendingWishlistAction';
43	
44	type PendingWishlistIntent = { intentId: string; timestamp: number };
45	
46	// A cancelled/abandoned IDP round-trip has no reliable "the user said no" signal we can
47	// observe here — the callback route that owns the actual redirect-back is base SFCC code,
48	// not this hook. Bound the blast radius by age instead: long enough for a slow IDP
49	// round-trip, short enough that an abandoned attempt can't misfire a much later, unrelated
50	// registration in the same tab.
51	const PENDING_WISHLIST_INTENT_MAX_AGE_MS = 5 * 60 * 1000; // 5 minutes
52	
53	// Reads the pending intent, transparently discarding (and clearing) one that's aged out.
54	const readPendingWishlistIntent = (): PendingWishlistIntent | undefined => {
55	  const stored = getSessionJSONItem(PENDING_WISHLIST_INTENT_KEY) as PendingWishlistIntent | undefined;
56	  if (!stored) return undefined;
57	  if (Date.now() - stored.timestamp > PENDING_WISHLIST_INTENT_MAX_AGE_MS) {
58	    clearSessionJSONItem(PENDING_WISHLIST_INTENT_KEY);
59	    return undefined;
60	  }
61	  return stored;
62	};
63	
64	const messages = defineMessages({
65	  drawerTitle: {
66	    id: 'wishlist.auth.drawer.title',
67	    defaultMessage: 'Wishlist',
68	  },
69	});
70	
71	const WISHLIST_DESCRIPTION = 'You must log in or create an account to add items to your wishlist.';
72	
73	type UseWishlistAuthDrawerParams = {
74	  onAuthSuccess?: () => void;
75	  /** Identifies which mounted instance initiated a social-IDP redirect, so that after the
76	   *  round-trip only the matching instance's `onAuthSuccess` fires — see
77	   *  `PENDING_WISHLIST_INTENT_KEY`'s comment. Must be stable and distinct per call site
78	   *  (e.g. `'header-wishlist'`, `'pdp-wishlist'`), not per render. */
79	  intentId: string;
80	};
81	
82	export type UseWishlistAuthDrawerReturn = {
83	  isOpen: boolean;
84	  handleDrawerClose: () => void;
85	  handleTriggerClick: (e: SyntheticEvent<HTMLElement>) => void;
86	  /** Ref pointing at the trigger element; passed to ZimmDrawer's finalFocusRef for AC10 focus-return. */
87	  triggerRef: RefObject<HTMLElement>;
88	  drawerTitle: string;
89	  description: string;
90	  emailValue: string;
91	  onEmailChange: (val: string) => void;
92	  onSendCode: () => Promise<{ success: boolean; error?: string } | void>;
93	  onSignInWithApple?: () => void;
94	  onSignInWithGoogle?: () => void;
95	  isSocialEnabled: boolean;
96	  /** Whether the passwordless email login flow is available per site config. */
97	  isPasswordlessEnabled: boolean;
98	  emailInputRef: RefObject<HTMLInputElement>;
99	  /** Error message from a failed social IDP sign-in attempt; absent when no failure has occurred. */
100	  socialError?: string;
101	  onCreateAccount: () => void;
102	  isOtpAuthOpen: boolean;
103	  onOtpAuthClose: () => void;
104	  form: UseFormReturn<FieldValues>;
105	  handlePasswordlessLogin: (email: string) => Promise<{ success: boolean; error?: string }>;
106	  handleOtpVerification: (pwdlessLoginToken: string) => Promise<{ success: boolean; error?: string }>;
107	  registerModal: ReturnType<typeof useAuthModal>;
108	};
109	
110	/**
111	 * Hook — owns all auth-gate state and SFCC SDK integration for the wishlist auth drawer.
112	 * Extracted from `ZimmWishlistAuthDrawer` so that component stays purely presentational.
113	 * Mirrors the same pattern used by SFCC's own `withRegistration` HOC.
114	 *
115	 * @returns All state and event handlers needed to render and drive the auth gate UI.
116	 */
117	export const useWishlistAuthDrawer = ({
118	  onAuthSuccess,
119	  intentId,
120	}: UseWishlistAuthDrawerParams): UseWishlistAuthDrawerReturn => {
121	  const { formatMessage } = useIntl();
122	  const { t } = useUiCopy();
123	  const { data: customer } = useCurrentCustomer();
124	  const { isRegistered } = useCustomerType();
125	  const { isOpen, onOpen, onClose } = useDisclosure();
126	  const [isOtpAuthOpen, setIsOtpAuthOpen] = useState(false);
127	  const [emailValue, setEmailValue] = useState('');
128	  const [socialError, setSocialError] = useState<string | undefined>();
