import { useEffect, useRef, useState } from 'react';
import type { RefObject, SyntheticEvent } from 'react';
import { defineMessages, useIntl } from 'react-intl';
import { useUiCopy } from 'app/hooks/useUiCopy';
import { useForm } from 'react-hook-form';
import type { UseFormReturn, FieldValues } from 'react-hook-form';
import { useDisclosure } from '@chakra-ui/react';
import {
  AuthHelpers,
  useAuthHelper,
  useCustomerType,
  useShopperBasketsV2Mutation as useShopperBasketsMutation,
} from '@salesforce/commerce-sdk-react';
import { useAuthModal, REGISTER_VIEW } from '@salesforce/retail-react-app/app/hooks/use-auth-modal';
import { getConfig } from '@salesforce/pwa-kit-runtime/utils/ssr-config';
import {
  getAuthorizePasswordlessErrorMessage,
  getLoginPasswordlessErrorMessage,
  getPasswordlessCallbackUrl,
} from '@salesforce/retail-react-app/app/utils/auth-utils';
import { API_ERROR_MESSAGE } from '@salesforce/retail-react-app/app/constants';
import {
  setSessionJSONItem,
  getSessionJSONItem,
  clearSessionJSONItem,
  buildRedirectURI,
} from '@salesforce/retail-react-app/app/utils/utils';
import useMultiSite from '@salesforce/retail-react-app/app/hooks/use-multi-site';
import { useCurrentCustomer } from '@salesforce/retail-react-app/app/hooks/use-current-customer';

// Matches the ZimmDrawer slide-in animation duration so focus/modal calls land after the
// panel is visible and Chakra's FocusLock has initialised.
const DRAWER_ANIMATION_DELAY_MS = 150;

// Social IDP sign-in triggers a full-page redirect — onAuthSuccess never fires. Persist an
// intent before the redirect so the pending wishlist action can be replayed on return.
// Keyed by `intentId` (see UseWishlistAuthDrawerParams) rather than a bare flag: the header
// and a PDP can both mount their own `useWishlistAuthDrawer` instance on the same returned
// page, each with a different `onAuthSuccess` — a bare boolean let whichever instance's
// effect ran first steal the intent and fire its own callback instead of the one that
// actually initiated the redirect (SFCC-742 review finding).
const PENDING_WISHLIST_INTENT_KEY = 'zimmPendingWishlistAction';

type PendingWishlistIntent = { intentId: string; timestamp: number };

// A cancelled/abandoned IDP round-trip has no reliable "the user said no" signal we can
// observe here — the callback route that owns the actual redirect-back is base SFCC code,
// not this hook. Bound the blast radius by age instead: long enough for a slow IDP
// round-trip, short enough that an abandoned attempt can't misfire a much later, unrelated
// registration in the same tab.
const PENDING_WISHLIST_INTENT_MAX_AGE_MS = 5 * 60 * 1000; // 5 minutes

// Reads the pending intent, transparently discarding (and clearing) one that's aged out.
const readPendingWishlistIntent = (): PendingWishlistIntent | undefined => {
  const stored = getSessionJSONItem(PENDING_WISHLIST_INTENT_KEY) as PendingWishlistIntent | undefined;
  if (!stored) return undefined;
  if (Date.now() - stored.timestamp > PENDING_WISHLIST_INTENT_MAX_AGE_MS) {
    clearSessionJSONItem(PENDING_WISHLIST_INTENT_KEY);
    return undefined;
  }
  return stored;
};

const messages = defineMessages({
  drawerTitle: {
    id: 'wishlist.auth.drawer.title',
    defaultMessage: 'Wishlist',
  },
});

const WISHLIST_DESCRIPTION = 'You must log in or create an account to add items to your wishlist.';

type UseWishlistAuthDrawerParams = {
  onAuthSuccess?: () => void;
  /** Identifies which mounted instance initiated a social-IDP redirect, so that after the
   *  round-trip only the matching instance's `onAuthSuccess` fires — see
   *  `PENDING_WISHLIST_INTENT_KEY`'s comment. Must be stable and distinct per call site
   *  (e.g. `'header-wishlist'`, `'pdp-wishlist'`), not per render. */
  intentId: string;
};

export type UseWishlistAuthDrawerReturn = {
  isOpen: boolean;
  handleDrawerClose: () => void;
  handleTriggerClick: (e: SyntheticEvent<HTMLElement>) => void;
  /** Ref pointing at the trigger element; passed to ZimmDrawer's finalFocusRef for AC10 focus-return. */
  triggerRef: RefObject<HTMLElement>;
  drawerTitle: string;
  description: string;
  emailValue: string;
  onEmailChange: (val: string) => void;
  onSendCode: () => Promise<{ success: boolean; error?: string } | void>;
  onSignInWithApple?: () => void;
  onSignInWithGoogle?: () => void;
  isSocialEnabled: boolean;
  /** Whether the passwordless email login flow is available per site config. */
  isPasswordlessEnabled: boolean;
  emailInputRef: RefObject<HTMLInputElement>;
  /** Error message from a failed social IDP sign-in attempt; absent when no failure has occurred. */
  socialError?: string;
  onCreateAccount: () => void;
  isOtpAuthOpen: boolean;
  onOtpAuthClose: () => void;
  form: UseFormReturn<FieldValues>;
  handlePasswordlessLogin: (email: string) => Promise<{ success: boolean; error?: string }>;
  handleOtpVerification: (pwdlessLoginToken: string) => Promise<{ success: boolean; error?: string }>;
  registerModal: ReturnType<typeof useAuthModal>;
};

/**
 * Hook — owns all auth-gate state and SFCC SDK integration for the wishlist auth drawer.
 * Extracted from `ZimmWishlistAuthDrawer` so that component stays purely presentational.
 * Mirrors the same pattern used by SFCC's own `withRegistration` HOC.
 *
 * @returns All state and event handlers needed to render and drive the auth gate UI.
 */
export const useWishlistAuthDrawer = ({
  onAuthSuccess,
  intentId,
}: UseWishlistAuthDrawerParams): UseWishlistAuthDrawerReturn => {
  const { formatMessage } = useIntl();
  const { t } = useUiCopy();
  const { data: customer } = useCurrentCustomer();
  const { isRegistered } = useCustomerType();
  const { isOpen, onOpen, onClose } = useDisclosure();
  const [isOtpAuthOpen, setIsOtpAuthOpen] = useState(false);
  const [emailValue, setEmailValue] = useState('');
  const [socialError, setSocialError] = useState<string | undefined>();
  // react-hook-form instance needed by SFCC's OtpAuth component for its internal field registration
  const form = useForm();
  // Points at the email input so Chakra's Drawer focuses it (not the close button) on open.
  const emailInputRef = useRef<HTMLInputElement>(null);

  // AC10 focus-return: capture the clicked/focused trigger element at click time.
  // React.cloneElement ref forwarding only works if the child uses forwardRef — not
  // guaranteed for all consumers. document.activeElement at onClick time is always the
  // element that was interacted with, regardless of how the child is implemented.
  // Typed as HTMLElement (not HTMLElement | null) to satisfy ZimmDrawer's finalFocusRef prop.
  const triggerRef = useRef<HTMLElement>(null as unknown as HTMLElement);

  const authorizePasswordlessLogin = useAuthHelper(AuthHelpers.AuthorizePasswordless);
  const loginPasswordless = useAuthHelper(AuthHelpers.LoginPasswordlessUser);
  const authorizeIDP = useAuthHelper(AuthHelpers.AuthorizeIDP);
  const mergeBasket = useShopperBasketsMutation('mergeBasket');
  // SFCC out-of-the-box registration modal — opened when the user clicks "Create an account"
  const registerModal = useAuthModal(REGISTER_VIEW);
  const { locale } = useMultiSite();

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const loginConfig = (getConfig().app.login || {}) as any;
  const passwordlessConfig = loginConfig.passwordless;
  const callbackURL = getPasswordlessCallbackUrl(passwordlessConfig?.callbackURI);
  const isSocialEnabled = !!loginConfig.social?.enabled;
  const idps: string[] = loginConfig.social?.idps ?? [];
  const socialRedirectPath: string = loginConfig.social?.redirectURI ?? '';
  const isPasswordlessEnabled = !!passwordlessConfig?.enabled;

  // Move focus to the email input once the drawer's enter animation completes.
  useEffect(() => {
    if (!isOpen) return;
    const timer = setTimeout(() => emailInputRef.current?.focus(), DRAWER_ANIMATION_DELAY_MS);
    return () => clearTimeout(timer);
  }, [isOpen]);

  // When the customer transitions to registered while the drawer (or OTP modal) is open,
  // close everything, fire the deferred action, and merge the guest basket the shopper was
  // just signed out of (passwordless login only — see the merge call's own comment below).
  useEffect(() => {
    if (isRegistered && (isOpen || isOtpAuthOpen)) {
      onClose();
      setIsOtpAuthOpen(false);
      onAuthSuccess?.();

      // Passwordless sign-in switches the SDK session to the registered customer without
      // merging the guest basket — left unmerged, the shopper's guest-basket items are
      // orphaned, not just miscounted. This mirrors base `use-auth-modal.js`'s own
      // `handleMergeBasket`, called from that file's structural equivalent of this effect
      // (its own `useEffect(..., [isRegistered])`) rather than from `handleOtpVerification` —
      // `isRegistered` (from `useCustomerType()`) is the signal that customer-dependent state
      // has actually caught up with the session switch, not just that the login mutation
      // resolved, which is presumably why base waits for it here too. The social-IDP route
      // needs no merge added here — it redirects through base `social-login-redirect`, which
      // already merges on its own. Create-account never reaches this branch — a new customer
      // has no prior basket to merge, and `handleTriggerClick` only opens this drawer for a
      // guest in the first place, so every path reaching this effect already started as a
      // guest session (unlike base, no `prevAuthType === 'guest'` check is needed to establish
      // that).
      //
      // Deliberately does not gate on `hasBasketItem` the way base does: that would add a new
      // basket-loading dependency to a hook that has never needed one, and the failure mode of
      // getting its timing wrong (a merge silently skipped when it shouldn't be) is worse than
      // the cost of one occasional harmless merge call against an empty basket.
      //
      // productItemMergeMode is 'sum_quantities', not the SDK's 'higher_quantity' default —
      // deliberate, not a copy of base's call. This changes the result of every merge, not
      // just over-the-cap ones: a guest who adds one unit of an item, then signs into an
      // account that already had one unit of that same item, gets two units after merge, not
      // one. No AC describes this, so a future reader/tester with no memory of this decision
      // needs it stated plainly: two units is intended.
      mergeBasket.mutate({
        headers: {
          // Not required since the request has no body, but CommerceAPI throws a
          // '419 - Unsupported Media Type' error if this header is removed.
          'Content-Type': 'application/json',
        },
        parameters: {
          createDestinationBasket: true,
          productItemMergeMode: 'sum_quantities',
        },
      });
    }
  }, [isRegistered]);

  // Social IDP sign-in redirects the page — the drawer closes and onAuthSuccess never fires.
  // On mount, if the shopper is already registered and a pending intent was stored before the
  // redirect, consume it immediately and clear the flag so it does not replay on subsequent
  // visits — but only when it's THIS instance's own intent (see PENDING_WISHLIST_INTENT_KEY's
  // comment): another `useWishlistAuthDrawer` instance mounted on the same returned page (e.g.
  // the header, alongside a PDP) leaves a non-matching intent untouched for its rightful owner.
  // Follows the same [isRegistered]-only dep pattern as the effect above: onAuthSuccess and
  // intentId are intentionally omitted because the intent fires at most once per redirect
  // cycle, and the flag is cleared before any re-render that could change either.
  useEffect(() => {
    if (!isRegistered) return;
    const pending = readPendingWishlistIntent();
    if (!pending || pending.intentId !== intentId) return;
    clearSessionJSONItem(PENDING_WISHLIST_INTENT_KEY);
    onAuthSuccess?.();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isRegistered]);

  const handleDrawerClose = () => {
    onClose();
    form.reset();
    setEmailValue('');
  };

  const handleTriggerClick = (e: SyntheticEvent<HTMLElement>) => {
    // e.currentTarget is always the element the handler is attached to — reliable across
    // mouse and keyboard, unlike document.activeElement which may still be body on click.
    triggerRef.current = e.currentTarget;
    if (customer?.isRegistered) {
      onAuthSuccess?.();
    } else {
      onOpen();
    }
  };

  const handlePasswordlessLogin = async (email: string) => {
    try {
      const redirectPath = window.location.pathname + (window.location.search ?? '');
      await authorizePasswordlessLogin.mutateAsync({
        userid: email,
        mode: passwordlessConfig?.mode,
        locale: locale.id,
        ...(callbackURL && {
          callbackURI: (() => {
            const url = new URL(callbackURL);
            url.searchParams.set('redirectUrl', redirectPath);
            return url.toString();
          })(),
        }),
      });
      return { success: true };
    } catch (error) {
      return {
        success: false,
        error: formatMessage(getAuthorizePasswordlessErrorMessage((error as Error).message)),
      };
    }
  };

  const handleOtpVerification = async (pwdlessLoginToken: string) => {
    try {
      await loginPasswordless.mutateAsync({ pwdlessLoginToken });
      return { success: true };
    } catch (e) {
      const errorData = await (e as { response?: { json: () => Promise<{ message: string }> } }).response?.json();
      return { success: false, error: formatMessage(getLoginPasswordlessErrorMessage(errorData?.message)) };
    }
  };

  const onSendCode = async () => {
    if (!isPasswordlessEnabled) return;
    const result = await handlePasswordlessLogin(emailValue);
    if (result.success) {
      onClose();
      // Brief delay lets the drawer finish its exit transition before OTP modal mounts.
      setTimeout(() => setIsOtpAuthOpen(true), DRAWER_ANIMATION_DELAY_MS);
    }
    return result;
  };

  const onSignInWithApple =
    isSocialEnabled && idps.includes('apple')
      ? async () => {
          setSocialError(undefined);
          try {
            setSessionJSONItem('returnToPage', window.location.pathname);
            // Persist the wishlist intent before the redirect — the page reloads after social
            // auth completes and onAuthSuccess would otherwise never fire.
            const intent: PendingWishlistIntent = { intentId, timestamp: Date.now() };
            setSessionJSONItem(PENDING_WISHLIST_INTENT_KEY, intent);
            await authorizeIDP.mutateAsync({
              hint: 'apple',
