              // here. useAppOrigin() calls useServerContext() which returns undefined in browser,
              // causing a destructuring throw; reading the origin directly avoids the SSR hook.
              redirectURI: buildRedirectURI(window.location.origin, socialRedirectPath),
            });
          } catch {
            // mutateAsync rejected before the browser navigated away (e.g. a network/config
            // error) — no redirect happened, so the intent just stored is already stale.
            // Clear it so it can't misfire a later, unrelated registration in this tab.
            clearSessionJSONItem(PENDING_WISHLIST_INTENT_KEY);
            setSocialError(formatMessage(API_ERROR_MESSAGE));
          }
        }
      : undefined;

  const onSignInWithGoogle =
    isSocialEnabled && idps.includes('google')
      ? async () => {
          setSocialError(undefined);
          try {
            setSessionJSONItem('returnToPage', window.location.pathname);
            // Persist the wishlist intent before the redirect — same reason as Apple above.
            const intent: PendingWishlistIntent = { intentId, timestamp: Date.now() };
            setSessionJSONItem(PENDING_WISHLIST_INTENT_KEY, intent);
            await authorizeIDP.mutateAsync({
              hint: 'google',
              // Social IDP redirects are browser-only — window.location.origin is always available
              // here. useAppOrigin() calls useServerContext() which returns undefined in browser,
              // causing a destructuring throw; reading the origin directly avoids the SSR hook.
              redirectURI: buildRedirectURI(window.location.origin, socialRedirectPath),
            });
          } catch {
            // Same reasoning as Apple's catch above — no redirect occurred, so clear the
            // just-stored intent rather than leaving it to misfire later.
            clearSessionJSONItem(PENDING_WISHLIST_INTENT_KEY);
            setSocialError(formatMessage(API_ERROR_MESSAGE));
          }
        }
      : undefined;

  const onCreateAccount = () => {
    handleDrawerClose();
    registerModal.onOpen();
  };

  return {
    isOpen,
    handleDrawerClose,
    handleTriggerClick,
    triggerRef,
    drawerTitle: formatMessage(messages.drawerTitle),
    description: t('login.drawer.wishlist.description', WISHLIST_DESCRIPTION),
    emailValue,
    onEmailChange: setEmailValue,
    onSendCode,
    onSignInWithApple,
    onSignInWithGoogle,
    isSocialEnabled,
    isPasswordlessEnabled,
    emailInputRef,
    socialError,
    onCreateAccount,
    isOtpAuthOpen,
    onOtpAuthClose: () => setIsOtpAuthOpen(false),
    form,
    handlePasswordlessLogin,
    handleOtpVerification,
    registerModal,
  };
};

